import { useState, useEffect, useRef } from 'react';
import Chart from 'chart.js/auto';

function Frame() {
  return (
    <div
      style={{
        backgroundColor: '#6ab4ff',
        width: '168px',
        height: '50px',
        borderRadius: '10px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '10px 37px',
        boxSizing: 'border-box',
      }}
    >
      <p
        style={{
          margin: 0,
          fontFamily: "'Inria Sans', 'Noto Sans KR', sans-serif",
          fontSize: '24px',
          lineHeight: 'normal',
          color: '#000',
        }}
      >
        스캔 시작
      </p>
    </div>
  );
}

function Frame1({ target, setTarget, onSubmit, loading }) {
  return (
    <div
      style={{
        width: '100%',
        height: '66px',
        backgroundColor: '#fff',
        position: 'relative',
        boxSizing: 'border-box',
      }}
    >
      <div
        aria-hidden="true"
        style={{
          position: 'absolute',
          inset: 0,
          border: '1px solid #505050',
          boxSizing: 'border-box',
          pointerEvents: 'none',
        }}
      />
      <form
        onSubmit={onSubmit}
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '8px 18px',
          boxSizing: 'border-box',
        }}
      >
        <input
          value={target}
          onChange={e => setTarget(e.target.value)}
          placeholder="예: scanme.nmap.org"
          style={{
            width: '100%',
            height: '50px',
            borderRadius: '8px',
            border: '1px solid #d1d5db',
            padding: '0 14px',
            fontSize: '16px',
            fontFamily: "'Noto Sans KR', sans-serif",
            outline: 'none',
            boxSizing: 'border-box',
          }}
        />
        <button
          type="submit"
          disabled={loading}
          style={{
            marginLeft: '16px',
            background: 'transparent',
            border: 'none',
            padding: 0,
            cursor: loading ? 'default' : 'pointer',
          }}
        >
          <Frame />
        </button>
      </form>
    </div>
  );
}

export default function Frame2() {
  const [target, setTarget] = useState('');
  const [scanData, setScanData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const assetChartRef = useRef(null);
  const vulnChartRef  = useRef(null);
  const riskChartRef  = useRef(null);


  const handleScan = async event => {
    event.preventDefault();
    setError('');
    setScanData(null);
    if (!target.trim()) {
      setError('IP 주소 또는 도메인을 입력하세요.');
      return;
    }

    setLoading(true);
    try {
      const response = await fetch('http://127.0.0.1:8000/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ target })
      });
      const data = await response.json();
      //const response = await fetch(`/api/scan?target=${encodeURIComponent(target)}`);
      if (!response.ok) {
        throw new Error(data.detail || '알 수 없는 오류가 발생했습니다.');
    }
      //throw new Error(`HTTP ${response.status}`);
      //}
      //const data = await response.json();
      setScanData(data);
    } catch (err) {
      console.error(err);
      setError('⚠ 스캔 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

 useEffect(() => {
  if (!scanData) return;

  // 1) 자산 차트 데이터
  new Chart(assetChartRef.current, {
    type: 'bar',
    data: {
      labels: ['Assets'],
      datasets: [{
        label: '개수',
        data: [scanData.assets.length],
        backgroundColor: ['#35607b']
      }]
    },
    options: { indexAxis: 'y' }
  });

  // 2) 취약점 심각도 데이터 세기
  const counts = { low:0, medium:0, high:0 };
  scanData.vulnerabilities.forEach(v => {
    if (counts[v.severity] !== undefined) counts[v.severity]++;
  });
  new Chart(vulnChartRef.current, {
    type: 'pie',
    data: {
      labels: ['low','medium','high'],
      datasets: [{
        data: [counts.low, counts.medium, counts.high],
        backgroundColor: ['green','orange','red']
      }]
    }
  });

  // 3) 위험도 분포 세기
  const rcounts = { safe:0, warning:0, danger:0 };
  scanData.risks.forEach(r => {
    if (rcounts[r.level] !== undefined) rcounts[r.level]++;
  });
  new Chart(riskChartRef.current, {
    type: 'doughnut',
    data: {
      labels: ['safe','warning','danger'],
      datasets: [{
        data: [rcounts.safe, rcounts.warning, rcounts.danger],
