        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '9px',
          width: '100%',
        }}
      >
        <div
          style={{
            display: 'flex',
            gap: '9px',
            flexDirection: 'column',
            width: '100%',
          }}
        >
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '2px',
            }}
          >
            <p
              style={{
                margin: 0,
                fontFamily: "'Inria Sans', 'Noto Sans KR', sans-serif",
                fontSize: '24px',
                lineHeight: 'normal',
                color: '#000',
