            lineHeight: 'normal',
            color: '#000',
          }}
        >
          결과 확인:
        </p>
        <div
          style={{
            width: '100%',
            height: '303px',
            backgroundColor: '#fff',
            position: 'relative',
            boxSizing: 'border-box',
